```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, notifier};
use wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count().min(u32::MAX as usize) as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {} fetched {}", seconds, fetched);

        // Retry a few times so a transient refusal does not leave the
        // report claiming a delivery that did not happen.
        let mut notified = false;
        for _ in 0..3 {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
